import GithubIcon from "@hugeicons/core-free-icons/GithubIcon"
import Globe02Icon from "@hugeicons/core-free-icons/Globe02Icon"
import WebhookIcon from "@hugeicons/core-free-icons/WebhookIcon"
import { HugeiconsIcon } from "@hugeicons/react-native"
import {
  ATTIO_LOGO_PATHS,
  ATTIO_LOGO_TRANSFORM,
  ATTIO_LOGO_VIEW_BOX,
} from "@repo/ui/lib/attio-logo"
import Svg, { G, Path } from "react-native-svg"

export type ConnectorKey =
  | "github"
  | "linear"
  | "datadog"
  | "attio"
  | "notion"
  | "cloudwatch"
  | "webhook"

const CONNECTORS: Record<
  ConnectorKey,
  { host: RegExp; tools: readonly string[] }
> = {
  github: {
    host: /(^|\.)github\.com$/i,
    tools: ["search_github", "fetch_github"],
  },
  linear: {
    host: /(^|\.)linear\.app$/i,
    tools: [
      "search_linear",
      "list_linear_issues",
      "fetch_linear",
      "create_linear_issue",
      "comment_linear",
      "update_linear_issue",
    ],
  },
  datadog: {
    host: /(^|\.)datadoghq\.(com|eu)$/i,
    tools: ["search_datadog_logs", "analyze_datadog_logs"],
  },
  attio: {
    host: /(^|\.)attio\.com$/i,
    tools: [
      "search_attio",
      "fetch_attio_record",
      "query_attio",
      "fetch_attio_activity",
    ],
  },
  notion: {
    host: /(^|\.)notion\.(so|site|com)$/i,
    tools: [
      "search_notion",
      "fetch_notion_page",
      "query_notion_data_source",
      "list_notion_users",
    ],
  },
  cloudwatch: {
    host: /(^|\.)console\.aws\.amazon\.com$/i,
    tools: [
      "list_cloudwatch_log_groups",
      "search_cloudwatch_logs",
      "list_cloudwatch_metrics",
      "get_cloudwatch_metrics",
    ],
  },
  // BYO inbound webhooks: no host, no tools — keeps the record exhaustive.
  webhook: {
    host: /$^/,
    tools: [],
  },
}

const connectorKeys = Object.keys(CONNECTORS) as ConnectorKey[]

export function connectorForTool(toolName: string): ConnectorKey | null {
  return (
    connectorKeys.find((key) => CONNECTORS[key].tools.includes(toolName)) ??
    null
  )
}

export function connectorForName(name?: string | null): ConnectorKey | null {
  if (!name) return null
  const normalized = name.toLowerCase()
  return connectorKeys.find((key) => key === normalized) ?? null
}

export function connectorForUrl(url?: string): ConnectorKey | null {
  if (!url) return null
  try {
    const host = new URL(url).hostname
    return connectorKeys.find((key) => CONNECTORS[key].host.test(host)) ?? null
  } catch {
    return null
  }
}

